["from verl.experimental.agent_loop.envs.asb_envs.BaseEnv import BaseEnv

class InventoryManagement(BaseEnv):
    def __init__(self, *, parameters=None):
        super().__init__()
        self.parameters = parameters if parameters is not None else {}
        self.inventory = self.parameters.get("inventory", [])

    def list_inventory(self):
        return {"success": True, "data": {"inventory": self.inventory}}

    def update_stock(self, *, item_id, new_quantity):
        for item in self.inventory:
            if item.get("item_id") == item_id:
                item["quantity"] = new_quantity
                return {"success": True}
        return {"success": False}

    def flag_inventory_issue(self, *, item_id, description):
        return {"success": True, "message": "Inventory issue flagged.", "item_id": item_id, "description": description}
